#include <windows.h>
#include <stdio.h>

int main() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token)) {
        return 1;
    }

    LUID luid = {};
    LookupPrivilegeValueA(nullptr, SE_CHANGE_NOTIFY_NAME, &luid);

    TOKEN_PRIVILEGES privileges = {};
    privileges.PrivilegeCount = 1;
    privileges.Privileges[0].Luid = luid;
    privileges.Privileges[0].Attributes = 0;

    TOKEN_PRIVILEGES previous = {};
    DWORD length = sizeof(previous);
    if (AdjustTokenPrivileges(token, FALSE, &privileges, sizeof(previous),
            &previous, &length) &&
        GetLastError() == ERROR_SUCCESS) {
        // Restore the previous state before closing the token.
        AdjustTokenPrivileges(token, FALSE, &previous, 0, nullptr, nullptr);
    }

    CloseHandle(token);
    return 0;
}

