#include <windows.h>
#include <stdio.h>

int main() {
    char name[256] = {};
    DWORD name_size = sizeof(name);
    if (!GetUserNameA(name, &name_size)) {
        return 1;
    }

    DWORD sid_size = 0;
    DWORD domain_size = 0;
    SID_NAME_USE use = SidTypeUser;
    LookupAccountNameA(nullptr, name, nullptr, &sid_size, nullptr,
        &domain_size, &use);

    auto sid = static_cast<PSID>(LocalAlloc(LPTR, sid_size));
    auto domain = static_cast<LPSTR>(LocalAlloc(LPTR, domain_size));
    if (sid != nullptr && domain != nullptr &&
        LookupAccountNameA(nullptr, name, sid, &sid_size, domain,
            &domain_size, &use)) {
        printf("Resolved %s\\%s\n", domain, name);
    }

    LocalFree(domain);
    LocalFree(sid);
    return 0;
}

