#include <windows.h>
#include <stdio.h>

int main() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &token)) {
        return 1;
    }

    DWORD length = 0;
    GetTokenInformation(token, TokenUser, nullptr, 0, &length);
    auto buffer = static_cast<PTOKEN_USER>(LocalAlloc(LPTR, length));
    if (buffer != nullptr &&
        GetTokenInformation(token, TokenUser, buffer, length, &length)) {
        printf("Token user information read.\n");
    }

    LocalFree(buffer);
    CloseHandle(token);
    return 0;
}

#include <windows.h>
#include <stdio.h>

int main() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_DUPLICATE, &token)) {
        return 1;
    }

    HANDLE duplicate = nullptr;
    if (DuplicateToken(token, SecurityImpersonation, &duplicate)) {
        if (SetThreadToken(nullptr, duplicate)) {
            // Passing NULL restores the thread's normal token.
            SetThreadToken(nullptr, nullptr);
        }
        CloseHandle(duplicate);
    }

    CloseHandle(token);
    return 0;
}
